const item = $('Research Ahent').first().json;
const report = typeof item.output === 'string' ? JSON.parse(item.output) : item.output;
const input = $('When Executed by Another Workflow').first().json;
const question = input.research_question;
if (typeof question !== 'string' || !question.trim() || report?.question?.trim() !== question.trim()) throw new Error('Research question was lost or changed.');
let requirements;
try { const raw = typeof input.requirements === 'string' ? input.requirements.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '') : input.requirements; requirements = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch { throw new Error('Required-answer checklist is not valid JSON.'); }
if (!Array.isArray(requirements) || requirements.length < 1 || requirements.length > 6 || requirements.some((r,i) => r?.id !== `R${i+1}` || typeof r.description !== 'string' || !r.description.trim())) throw new Error('Required-answer checklist is invalid.');
const ids = new Set(requirements.map(r => r.id));
const pages = new Map();
const source_images = [];
const tool_errors = Array.isArray(report.tool_errors) ? [...report.tool_errors] : [];
function absorb(value) {
  if (typeof value === 'string') { try { value = JSON.parse(value); } catch { return; } }
  for (const response of Array.isArray(value) ? value : [value]) for (const page of response?.results ?? []) {
    if (typeof page.url !== 'string') continue;
    if (typeof page.raw_content === 'string') pages.set(page.url, page.raw_content);
    for (const image of page.images ?? []) {
      const image_url = typeof image === 'string' ? image : image?.url;
      if (typeof image_url === 'string' && /^https:\/\//i.test(image_url)) source_images.push({source_url:page.url,image_url});
    }
  }
}
for (const step of item.intermediateSteps ?? []) if (String(step.action?.tool ?? '').includes('Extract')) absorb(step.observation);
try { absorb($('Re-extract cited pages').first().json); }
catch { tool_errors.push('Separate Tavily extraction did not return readable content.'); }
const accepted_passages = [], rejected_passages = [];
const missing_evidence = Array.isArray(report.missing_evidence) ? [...report.missing_evidence] : [];
const seen = new Set();
for (const source of report.sources ?? []) for (const passage of source.passages ?? []) {
  const url = typeof source.url === 'string' ? source.url : '';
  const quote = typeof passage.quote === 'string' ? passage.quote : '';
  const requirement_ids = Array.isArray(passage.requirement_ids) ? passage.requirement_ids.filter(id => ids.has(id)) : [];
  const entry = {url,...passage,requirement_ids};
  let reason = '';
  if (!/^https?:\/\/[^\s/?#]+\.[^\s/?#]+(?:[/?#]\S*)?$/i.test(url)) reason = 'Invalid source URL';
  if (!reason && !quote.trim()) reason = 'Empty quotation';
  if (!reason && !['direct','related'].includes(passage.relevance)) reason = 'Unclassified relevance';
  if (!reason && !pages.has(url)) reason = 'No extracted page text for URL';
  if (!reason && !pages.get(url).includes(quote)) reason = 'Quotation absent from extracted page';
  if (!reason && passage.relevance === 'direct' && !requirement_ids.length) reason = 'Direct quote is not linked to a required answer';
  if (reason) { rejected_passages.push({...entry,reason}); missing_evidence.push(`Unverified evidence at ${url || 'unknown URL'}: ${reason}.`); continue; }
  const key = url+'\u0000'+quote;
  if (!seen.has(key)) { accepted_passages.push(entry); seen.add(key); }
}
const covered = new Set(accepted_passages.filter(p => p.relevance === 'direct').flatMap(p => p.requirement_ids));
const uncovered_requirements = requirements.filter(r => !covered.has(r.id));
for (const r of uncovered_requirements) missing_evidence.push(`${r.id}: ${r.description}`);
const image_candidates = [];
for (const c of report.image_candidates ?? []) {
  if (image_candidates.length >= 2) break;
  if (!c || typeof c.source_url !== 'string' || typeof c.image_url !== 'string' || typeof c.license_quote !== 'string' || typeof c.caption !== 'string') continue;
  if (!/^https:\/\//i.test(c.image_url) || !source_images.some(i => i.source_url === c.source_url && i.image_url === c.image_url)) continue;
  if (!accepted_passages.some(p => p.url === c.source_url)) continue;
  if (!pages.get(c.source_url)?.includes(c.license_quote)) continue;
  if (!/(public domain|creative commons|cc\s?by|cc0|may be reused|free to use|reuse permitted)/i.test(c.license_quote) || /all rights reserved|permission required/i.test(c.license_quote)) continue;
  image_candidates.push({source_url:c.source_url,image_url:c.image_url,caption:c.caption,license_quote:c.license_quote});
}
const needs_review = uncovered_requirements.length > 0 || missing_evidence.length > 0;
return [{json:{question,requirements,accepted_passages,rejected_passages,missing_evidence,tool_errors,source_images,image_candidates,uncovered_requirements,needs_review,verification_status:covered.size ? 'quote_checked' : 'insufficient'}}];

