const initial = $('Verify original quotations').first().json;
const item = $input.first().json;
const review = typeof item.output === 'string' ? JSON.parse(item.output) : item.output;
if (review?.question?.trim() !== initial.question.trim()) throw new Error('Verifier changed the original question.');
const ids = new Set(initial.requirements.map(r => r.id));
const original = new Map((initial.accepted_passages ?? []).map(p => [p.url+'\u0000'+p.quote,p]));
const accepted_passages = [], rejected_passages = [...(initial.rejected_passages ?? [])];
const tool_errors = [...(initial.tool_errors ?? []),...(review.tool_errors ?? [])];
const missing_evidence = [...(review.unresolved ?? [])];
const seen = new Set();
// Keep already covered items, but require independent review of any existing quote claimed for a gap.
const previouslyCovered = new Set(initial.requirements.filter(r => !initial.uncovered_requirements.some(u => u.id === r.id)).map(r => r.id));
for (const [key,p] of original) if (p.requirement_ids.some(id => previouslyCovered.has(id))) {accepted_passages.push(p);seen.add(key);}
for (const approval of review.approved_existing ?? []) {
  const key = approval.url+'\u0000'+approval.quote;
  if (!original.has(key)) continue;
  const p = original.get(key);
  const newIds = (approval.requirement_ids ?? []).filter(id => ids.has(id) && initial.uncovered_requirements.some(r => r.id === id));
  if (newIds.length && typeof approval.reason === 'string' && approval.reason.trim()) {
    const merged = {...p,requirement_ids:[...new Set([...p.requirement_ids,...newIds])]};
    const ix = accepted_passages.findIndex(x => x.url === p.url && x.quote === p.quote);
    if (ix >= 0) accepted_passages[ix] = merged; else {accepted_passages.push(merged);seen.add(key);}
  }
}
for (const [key,p] of original) if (!seen.has(key)) rejected_passages.push({...p,reason:'Verifier did not establish support for a required answer'});
const pages = new Map(), observedImages=[];
for (const step of item.intermediateSteps ?? []) if (String(step.action?.tool ?? '').includes('Extract')) {
  try {
    const v=typeof step.observation==='string'?JSON.parse(step.observation):step.observation;
    for (const response of Array.isArray(v)?v:[v]) for (const page of response?.results??[]) {
      if (typeof page.url==='string' && typeof page.raw_content==='string') pages.set(page.url,page.raw_content);
      for (const image of page.images??[]) observedImages.push({source_url:page.url,image_url:typeof image==='string'?image:image?.url});
    }
  } catch {tool_errors.push('Verifier Extract response could not be parsed.');}
}
for (const source of review.sources ?? []) for (const p of source.passages ?? []) {
  const url=source.url??'',quote=p.quote??'';
  const requirement_ids=(p.requirement_ids??[]).filter(id=>ids.has(id)&&initial.uncovered_requirements.some(r=>r.id===id));
  let reason='';
  if (!/^https?:\/\/[^\s/?#]+\.[^\s/?#]+(?:[/?#]\S*)?$/i.test(url)) reason='Invalid source URL';
  if (!reason && (!quote || !pages.has(url) || !pages.get(url).includes(quote))) reason='New quote absent from extracted page';
  if (!reason && p.relevance==='direct' && !requirement_ids.length) reason='New direct quote does not answer an uncovered item';
  if (!reason && !['direct','related'].includes(p.relevance)) reason='Unclassified relevance';
  if (reason) {rejected_passages.push({url,...p,reason});missing_evidence.push(`Unverified new evidence at ${url||'unknown URL'}: ${reason}.`);continue;}
  const key=url+'\u0000'+quote;
  if (!seen.has(key)) {accepted_passages.push({url,...p,requirement_ids});seen.add(key);}
}
const covered=new Set(accepted_passages.filter(p=>p.relevance==='direct').flatMap(p=>p.requirement_ids));
const uncovered_requirements=initial.requirements.filter(r=>!covered.has(r.id));
for (const r of uncovered_requirements) missing_evidence.push(`${r.id}: ${r.description}`);
const image_candidates=[...(initial.image_candidates??[])];
for (const c of review.image_candidates??[]) {
  if (image_candidates.length>=2) break;
  if (!c || typeof c.source_url!=='string' || typeof c.image_url!=='string' || typeof c.caption!=='string' || typeof c.license_quote!=='string') continue;
  if (!/^https:\/\//i.test(c.image_url) || !observedImages.some(i=>i.source_url===c.source_url&&i.image_url===c.image_url)) continue;
  if (!accepted_passages.some(p=>p.url===c.source_url) || !pages.get(c.source_url)?.includes(c.license_quote)) continue;
  if (!/(public domain|creative commons|cc\s?by|cc0|may be reused|free to use|reuse permitted)/i.test(c.license_quote) || /all rights reserved|permission required/i.test(c.license_quote)) continue;
  image_candidates.push({source_url:c.source_url,image_url:c.image_url,caption:c.caption,license_quote:c.license_quote});
}
return [{json:{question:initial.question,requirements:initial.requirements,accepted_passages,rejected_passages,missing_evidence:[...new Set(missing_evidence)],tool_errors,image_candidates,uncovered_requirements,needs_review:false,verification_status:covered.size?'reviewed':'insufficient'}}];
